def multipliers(x):

    divisors = []
    divisor = 2
    stop = math.sqrt(x)
    while x != 1 and divisor <= stop:

        if x % divisor == 0:

            x //= divisor
            divisors.append(divisor)

        else:

            divisor += 1

    if x != 1:

        divisors.append(x)

